1	import { createServer } from 'node:http';
2	import type { IncomingMessage, ServerResponse } from 'node:http';
3	import { lstatSync, mkdirSync, readFileSync, renameSync, unlinkSync, writeFileSync } from 'node:fs';
4	import { join } from 'node:path';
5	import { randomUUID } from 'node:crypto';
6	import {
7	  FIELD_LIMITS,
8	  checkIdeaContent,
9	  isCompleteIdea,
10	  normalizeIdea,
11	  fieldRulesBrowserScript,
12	  type ContentErrorCode,
13	} from './idea-fields.ts';
14	
15	const PRODUCT: string = 'FeatureHarbor';
16	const RESOURCE: string = 'ideas';
17	const MAX_BODY_BYTES = 1_000_000;
18	// 接口侧把共用的内容判定结果映射成原有的错误说明；首页另有自己的措辞。
19	const CONTENT_ERROR_MESSAGES: Record<ContentErrorCode, string> = {
20	  'title-empty': '标题去掉首尾空白后不能为空',
21	  'title-too-long': `标题最多 ${FIELD_LIMITS.title} 个字符`,
22	  'description-empty': '详细说明必须包含非空白内容',
23	  'description-too-long': `详细说明最多 ${FIELD_LIMITS.description} 个字符`,
24	  'scenario-too-long': `使用场景最多 ${FIELD_LIMITS.scenario} 个字符`,
25	};
26	const PAGE: string = `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FeatureHarbor · 产品意见与公开路线图</title><style>
27	body{font-family:system-ui,sans-serif;max-width:52rem;margin:3rem auto;padding:0 1rem;line-height:1.7}
28	a{color:#175b9c}
29	label{display:block;font-weight:600;margin-top:1rem}
30	input,textarea{width:100%;box-sizing:border-box;padding:.4rem;font:inherit}
31	textarea{resize:vertical}
32	.required{color:#b00020}
33	button{margin-top:1rem;padding:.5rem 1.2rem;font:inherit}
34	#error{color:#b00020;margin-top:.75rem}
35	#success{color:#1a7f37;margin-top:.75rem}
36	.idea{border-top:1px solid #ddd;padding:1rem 0}
37	.idea h3{margin:0 0 .5rem}
38	.pre{white-space:pre-wrap}
39	time{color:#666;font-size:.9rem}
40	#search-form{margin:1rem 0}
41	#search-form input{max-width:20rem;margin-right:.5rem}
42	#search-form button{margin-top:.25rem;margin-right:.5rem}
43	</style><main><h1>FeatureHarbor</h1><p>产品意见与公开路线图</p>
44	<h2>提交产品意见</h2>
45	<form id="idea-form" novalidate>
46	<label for="f-title">标题 <span class="required">*</span>（必填，最多 ${FIELD_LIMITS.title} 字）</label>
47	<input id="f-title" name="title" required>
48	<label for="f-desc">详细说明 <span class="required">*</span>（必填，最多 ${FIELD_LIMITS.description} 字）</label>
49	<textarea id="f-desc" name="description" rows="5" required></textarea>
50	<label for="f-scenario">使用场景（可选，最多 ${FIELD_LIMITS.scenario} 字）</label>
51	<textarea id="f-scenario" name="scenario" rows="3"></textarea>
52	<button type="submit">提交意见</button>
53	<p id="error" role="alert" hidden></p>
54	<p id="success" role="status" hidden></p>
55	</form>
56	<h2>意见列表</h2>
57	<form id="search-form" role="search" novalidate>
58	<label for="f-search">关键词搜索</label>
59	<input id="f-search" name="q" type="search" placeholder="搜索标题、详细说明或使用场景" autocomplete="off">
60	<button type="submit">搜索</button>
61	<button id="search-clear" type="button">清空</button>
62	</form>
63	<p id="empty" hidden>还没有意见记录。</p>
64	<div id="ideas"></div>
65	<p><a href="/api/ideas">查看意见列表接口</a> · <a href="/health">服务状态</a></p>
66	</main><script>
67	${fieldRulesBrowserScript}
68	const form = document.getElementById('idea-form');
69	const titleInput = document.getElementById('f-title');
70	const descInput = document.getElementById('f-desc');
71	const scenarioInput = document.getElementById('f-scenario');
72	const errorBox = document.getElementById('error');
73	const successBox = document.getElementById('success');
74	const emptyNote = document.getElementById('empty');
75	const list = document.getElementById('ideas');
76	const searchForm = document.getElementById('search-form');
77	const searchInput = document.getElementById('f-search');
78	const searchClear = document.getElementById('search-clear');
79	const EMPTY_TEXT = '还没有意见记录。';
80	const NOT_FOUND_TEXT = '没有找到符合关键词的意见。';
81	const LOAD_FAILED_TEXT = '意见列表加载失败，请稍后刷新重试。';
82	// 首次列表请求的状态：loading（进行中）/ ready（成功）/ failed（失败）
83	let listState = 'loading';
84	// 已生效的搜索关键词：去掉首尾空白后的完整一段文字，空字符串表示不搜索。
85	// 只影响当前页面的可见结果，不发起请求、不改变已保存记录与接口返回。
86	let activeKeyword = '';
87	// 纯文字的大小写不敏感包含判断：关键词内部空格按原文参与比较，
88	// 不拆词；标点、尖括号与看起来像正则表达式的文字都按普通文字查找，
89	// 因此直接用 includes，不能走正则。
90	function ideaMatches(idea, keyword) {
91	  const needle = keyword.toLowerCase();
92	  return idea.title.toLowerCase().includes(needle)
93	    || idea.description.toLowerCase().includes(needle)
94	    || idea.scenario.toLowerCase().includes(needle);
95	}
96	function showError(message) {
97	  errorBox.textContent = message;
98	  errorBox.hidden = false;
99	  successBox.hidden = true;
100	}
101	function renderIdea(idea) {
102	  const item = document.createElement('article');
103	  item.className = 'idea';
104	  const heading = document.createElement('h3');
105	  heading.textContent = idea.title;
106	  const desc = document.createElement('p');
107	  desc.className = 'pre';
108	  desc.textContent = idea.description;
109	  item.append(heading, desc);
110	  if (typeof idea.scenario === 'string' && idea.scenario.trim().length > 0) {
111	    const scenario = document.createElement('p');
112	    const label = document.createElement('strong');
113	    label.textContent = '使用场景：';
114	    const text = document.createElement('span');
115	    text.className = 'pre';
116	    text.textContent = idea.scenario;
117	    scenario.append(label, text);
118	    item.append(scenario);
119	  }
120	  const time = document.createElement('time');
121	  time.dateTime = idea.createdAt;
122	  const parsed = new Date(idea.createdAt);
123	  time.textContent = isNaN(parsed.getTime()) ? String(idea.createdAt) : parsed.toLocaleString();
124	  item.append(time);
125	  return item;
126	}
127	let remoteIdeas = [];
128	// 本页已确认保存的意见，按本页发起提交的先后排列：后提交的在前。
129	// 每条记录带上点击提交时的序号，响应返回的先后不影响排列位置
130	const submittedIdeas = [];
131	function renderList() {
132	  // 以服务端标识 id 去重后合并：本页提交成功的意见在前，其后补入首次响应中的其他记录
133	  const seen = new Set();
134	  const ordered = [];
135	  for (const entry of submittedIdeas) {
136	    const idea = entry.idea;
137	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
138	  }
139	  for (const idea of remoteIdeas) {
140	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
141	  }
142	  // 搜索只过滤当前页面的可见结果：沿用合并后的原有顺序，逐条判断、不去重不重排，
143	  // 同一条意见最多出现一次；匹配的意见仍按原文渲染（保留空白与换行），不删改内容。
144	  const visible = activeKeyword
145	    ? ordered.filter((idea) => ideaMatches(idea, activeKeyword))
146	    : ordered;
147	  list.replaceChildren(...visible.map(renderIdea));
148	  if (listState === 'failed') {
149	    // 加载失败优先显示现有的失败提示，不能把失败显示成搜索无结果
150	    emptyNote.textContent = LOAD_FAILED_TEXT;
151	    emptyNote.hidden = false;
152	  } else if (listState !== 'ready') {
153	    // 首次列表仍在加载，不能把等待误报成没有记录或没有匹配结果
154	    emptyNote.hidden = true;
155	  } else if (activeKeyword) {
156	    // 搜索已生效：完整列表是否为空决定提示措辞，已有意见但无匹配时明确提示未找到
157	    emptyNote.textContent = ordered.length === 0 ? EMPTY_TEXT : NOT_FOUND_TEXT;
158	    emptyNote.hidden = visible.length > 0;
159	  } else {
160	    emptyNote.textContent = EMPTY_TEXT;
161	    emptyNote.hidden = ordered.length > 0;
162	  }
163	}
164	// 一条意见记录是否完整，直接使用 idea-fields.ts 注入的同一份 isCompleteIdea：
165	// 与服务读取已有数据的判定逐字相同，列表加载与提交确认都调用它，不在页面另写第二份。
166	async function loadIdeas() {
167	  try {
168	    const res = await fetch('/api/ideas');
169	    if (!res.ok) throw new Error('load failed');
170	    const data = await res.json();
171	    // 列表响应必须是带 ideas 数组的 JSON 对象，且数组中每条记录都完整；
172	    // 顶层结构异常或任意一条记录不完整都属于整次加载失败，
173	    // 即使异常记录前面有正常意见，也不能只展示其中一部分
174	    if (typeof data !== 'object' || data === null || Array.isArray(data) || !Array.isArray(data.ideas)) {
175	      throw new Error('invalid ideas response');
176	    }
177	    if (!data.ideas.every(isCompleteIdea)) throw new Error('invalid idea record');
178	    remoteIdeas = data.ideas;
179	    listState = 'ready';
180	  } catch {
181	    listState = 'failed';
182	  }
183	  renderList();
184	}
185	// 任一字段每次发生编辑都递增；提交时记下当前版本，成功响应到达时若版本未变，
186	// 说明等待期间没有继续编辑，才清空表单，否则保留正在写的草稿
187	let editVersion = 0;
188	for (const field of [titleInput, descInput, scenarioInput]) {
189	  field.addEventListener('input', () => { editVersion += 1; });
190	}
191	// 字段内容判定与接口共用同一份实现（FIELD_LIMITS、codePointCount、checkIdeaContent
192	// 由 idea-fields.ts 注入）；这里只把共用判定结果映射成本页原有的提示措辞与顺序。
193	function validate(title, description, scenario) {
194	  switch (checkIdeaContent(title, description, scenario)) {
195	    case 'title-empty': return '标题不能为空。';
196	    case 'title-too-long': return '标题最多 ' + FIELD_LIMITS.title + ' 个字符。';
197	    case 'description-empty': return '详细说明不能为空。';
198	    case 'description-too-long': return '详细说明最多 ' + FIELD_LIMITS.description + ' 个字符。';
199	    case 'scenario-too-long': return '使用场景最多 ' + FIELD_LIMITS.scenario + ' 个字符。';
200	    default: return null;
201	  }
202	}
203	// 每次点击提交都递增：成功或失败提示只属于最近一次点击。
204	// 更早发出的请求即使更晚返回，也只能在服务确认保存时更新列表，不能改动当前提示。
205	let latestSubmitSeq = 0;
206	form.addEventListener('submit', async (event) => {
207	  event.preventDefault();
208	  const submitSeq = ++latestSubmitSeq;
209	  // 用户发起新的提交后，上一条操作的提示先清除；在本次点击有结果前，
210	  // 更早请求迟到返回也不能重新显示成功或失败，也不能让人误以为正在提交的意见已保存
211	  errorBox.hidden = true;
212	  successBox.hidden = true;
213	  const title = titleInput.value;
214	  const description = descInput.value;
215	  const scenario = scenarioInput.value;
216	  const submittedVersion = editVersion;
217	  const problem = validate(title, description, scenario);
218	  // 被表单直接拦下的一次点击同样是用户最近的提交操作，字段错误即本次点击的结果；
219	  // 之后更早请求的返回不能掩盖它
220	  if (problem) { showError(problem); return; }
221	  let res;
222	  try {
223	    res = await fetch('/api/ideas', {
224	      method: 'POST',
225	      headers: { 'content-type': 'application/json' },
226	      body: JSON.stringify({ title, description, scenario })
227	    });
228	  } catch {
229	    if (submitSeq === latestSubmitSeq) showError('网络错误，提交未成功，请重试。');
230	    return;
231	  }
232	  let data = null;
233	  try { data = await res.json(); } catch { data = null; }
234	  if (!res.ok) {
235	    if (submitSeq === latestSubmitSeq) {
236	      showError(data && data.error ? '提交失败：' + data.error : '提交失败，请稍后重试。');
237	    }
238	    return;
239	  }
240	  // 成功状态的响应同样必须记录完整：顶层是含 idea 的 JSON 对象，
241	  // 且 idea 本身通过 isCompleteIdea 校验（对象、非空 id、各字段均为字符串）。
242	  // 空对象、数组或缺字段的记录不能当作保存成功：不显示成功提示、
243	  // 不清空草稿、不并入列表，也不用表单内容补齐响应缺失的信息
244	  const saved = typeof data === 'object' && data !== null && !Array.isArray(data) && isCompleteIdea(data.idea);
245	  if (!saved) {
246	    if (submitSeq === latestSubmitSeq) showError('提交失败，请稍后重试。');
247	    return;
248	  }
249	  const idea = data.idea;
250	  // 是否清空表单只取决于等待期间有没有继续编辑（包括改回原文、清空字段也算编辑），
251	  // 与响应返回先后无关：过期请求确认保存时也不能清掉用户正在写的草稿
252	  if (editVersion === submittedVersion) form.reset();
253	  // 只要服务确认保存，意见就进入列表，即使这条请求已不是最近一次点击：
254	  // 不能为了避免提示干扰而丢弃真实保存结果。
255	  // 位置按本页发起提交的先后确定（后提交的在前），与响应返回先后无关：
256	  // 先提交的意见迟到确认时补到后提交的意见之后，不能把它挤到更靠后的位置
257	  const entry = { seq: submitSeq, idea };
258	  let insertAt = submittedIdeas.findIndex((e) => e.seq < submitSeq);
259	  if (insertAt === -1) insertAt = submittedIdeas.length;
260	  submittedIdeas.splice(insertAt, 0, entry);
261	  renderList();
262	  // 成功提示只属于最近一次点击：更早的请求迟到返回时，不能在最新一次的失败提示
263	  // 或新一次提交的等待旁边再显示成功
264	  if (submitSeq === latestSubmitSeq) {
265	    successBox.textContent = '提交成功，你的意见已保存。';
266	    successBox.hidden = false;
267	  }
268	});
269	// 搜索只在本页过滤已合并的完整列表：提交搜索表单不发起任何请求、不提交意见，
270	// 也不清空或改写提交意见表单里的草稿；关键词去掉首尾空白后为空时恢复完整列表。
271	// 已生效后，迟到的首次列表与本页新确认保存的意见都会在 renderList 中继续按它过滤。
272	function applySearch() {
273	  activeKeyword = searchInput.value.trim();
274	  renderList();
275	}
276	searchForm.addEventListener('submit', (event) => {
277	  event.preventDefault();
278	  applySearch();
279	});
280	searchClear.addEventListener('click', () => {
281	  searchInput.value = '';
282	  activeKeyword = '';
283	  renderList();
284	});
285	loadIdeas();
286	</script></html>`;
287	const args: string[] = process.argv.slice(2);
288	const help: string = `FeatureHarbor - 产品意见与公开路线图
289	Usage: node server.ts serve [--host ADDRESS] [--port PORT] [--data-dir DIRECTORY]
290	       node server.ts --help
291	Defaults: --host 127.0.0.1 --port 8080 --data-dir data
292	Port 0 selects an available port.
293	`;
294	if (args.length === 0 || args.includes('--help') || args.includes('-h')) {
295	  process.stdout.write(help);
296	  process.exit(args.length === 0 ? 2 : 0);
297	}
298	if (args.shift() !== 'serve') { console.error('Expected serve or --help'); process.exit(2); }
299	let host: string = '127.0.0.1';
300	let port: number = 8080;
301	let dataDir: string = 'data';
302	while (args.length) {
303	  const flag = args.shift();
304	  const value = args.shift();
305	  if (!value || !['--host', '--port', '--data-dir'].includes(flag ?? '')) {
306	    console.error('Each option must be --host, --port or --data-dir followed by a value'); process.exit(2);
307	  }
308	  if (flag === '--host') host = value;
309	  else if (flag === '--port') {
310	    if (!/^\d+$/.test(value) || Number(value) > 65535) { console.error('Port must be between 0 and 65535'); process.exit(2); }
311	    port = Number(value);
312	  } else dataDir = value;
313	}
314	mkdirSync(dataDir, { recursive: true });
315	const dataFile = join(dataDir, 'ideas.json');
316	try { writeFileSync(dataFile, '[]\n', { flag: 'wx' }); } catch (error) {
317	  if (!(error instanceof Error && 'code' in error && error.code === 'EEXIST')) throw error;
318	}
319	function respond(res: ServerResponse, status: number, value: unknown, options: { html?: boolean; allow?: string } = {}): void {
320	  const body = options.html ? String(value) : JSON.stringify(value);
321	  res.writeHead(status, { 'content-type': options.html ? 'text/html; charset=utf-8' : 'application/json; charset=utf-8',
322	    'content-length': Buffer.byteLength(body), ...(status === 405 ? { allow: options.allow ?? 'GET' } : {}) });
323	  res.end(body);
324	}
325	// 已有意见的结构完整性直接使用 idea-fields.ts 的 isCompleteIdea，
326	// 与首页列表加载、提交结果确认共用同一份判定。
327	function readIdeas(): unknown[] {
328	  const records: unknown = JSON.parse(readFileSync(dataFile, 'utf8'));
329	  if (!Array.isArray(records)) throw new Error('Invalid record list');
330	  // 任意一条记录不完整，整份列表都视为读取失败：
331	  // 不跳过异常记录，也不只返回正常部分。只检查结构，不套用新提交的内容限制：
332	  // 标题首尾空白、正文与场景换行、任意时间字符串都按原样保留，不补字段或改写文字。
333	  if (!records.every(isCompleteIdea)) throw new Error('Invalid idea record');
334	  return records;
335	}
336	function saveIdeas(records: unknown[]): void {
337	  const tempFile = `${dataFile}.tmp`;
338	  writeFileSync(tempFile, `${JSON.stringify(records, null, 2)}\n`);
339	  try {
340	    renameSync(tempFile, dataFile);
341	  } catch (error) {
342	    // 临时内容已写入但替换正式文件失败：尽量删除本次写出的临时普通文件，
343	    // 不让未保存成功的内容留下可被误认成已保存数据的副本。
344	    // 清理只针对普通文件——临时路径若是目录等本就不是本次写出的形态，一律不动；
345	    // 清理本身失败（如权限限制）只放弃清理，不掩盖原有的保存失败。
346	    try {
347	      if (lstatSync(tempFile).isFile()) unlinkSync(tempFile);
348	    } catch {
349	      // 忽略清理异常：保存失败的结果不变
350	    }
351	    throw error;
352	  }
353	}
354	async function handleCreateIdea(req: IncomingMessage, res: ServerResponse): Promise<void> {
355	  // 请求大小上限按实际收到的字节累计：JSON 的括号、引号、字段名与空白都计入，
356	  // 中文、表情按 UTF-8 编码后的字节数计入；这与字段按 Unicode 码点的上限是两回事。
357	  const declaredLength = Number(req.headers['content-length']);
358	  let tooLarge = Number.isFinite(declaredLength) && declaredLength > MAX_BODY_BYTES;
359	  const chunks: Buffer[] = [];
360	  let size = 0;
361	  // 超限后不能写出 400 就立即 req.destroy()：客户端可能还在发送，强断会让它只看到
362	  // 连接断开，读不到完整错误。这里继续把请求体读完（排空，天然带背压），
363	  // 等请求正常结束后再回复，客户端只要发完并保持连接等待，就能收到完整可解析的 400。
364	  // 超限后的字节不再缓存：绝不能拿已收到的前缀去解析，更不能截断后尝试保存。
365	  try {
366	    for await (const chunk of req as AsyncIterable<Buffer>) {
367	      size += chunk.length;
368	      if (tooLarge) continue;
369	      if (size > MAX_BODY_BYTES) {
370	        tooLarge = true;
371	        chunks.length = 0;
372	        continue;
373	      }
374	      chunks.push(chunk);
375	    }
376	  } catch {
377	    // 客户端中途断开或请求流出错：响应已无处可写，安静结束，不能变成 500。
378	    req.destroy();
379	    return;
380	  }
381	  // 无论是否预先声明长度（Content-Length）还是分段传输（Transfer-Encoding: chunked）、
382	  // 超出发生在中途还是末段，都按同一条规则拒绝；即使正文同时不是合法 JSON，
383	  // 理由也仍是“请求体过大”，不能被后续的 JSON 解析替换成别的错误。
384	  // 恰好达到上限（size === MAX_BODY_BYTES）不在这里拒绝，继续按 JSON 与字段规则判断。
385	  if (tooLarge) {
386	    respond(res, 400, { error: '请求体过大' });
387	    return;
388	  }
389	  let payload: unknown;
390	  try {
391	    payload = JSON.parse(Buffer.concat(chunks).toString('utf8'));
392	  } catch {
393	    respond(res, 400, { error: '请求体不是有效的 JSON' });
394	    return;
395	  }
396	  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
397	    respond(res, 400, { error: '请求体必须是 JSON 对象' });
398	    return;
399	  }
400	  const body = payload as Record<string, unknown>;
401	  for (const field of ['title', 'description'] as const) {
402	    if (body[field] === undefined) { respond(res, 400, { error: `缺少必填字段 ${field}` }); return; }
403	    if (typeof body[field] !== 'string') { respond(res, 400, { error: `字段 ${field} 必须是字符串` }); return; }
404	  }
405	  if (body.scenario !== undefined && typeof body.scenario !== 'string') {
406	    respond(res, 400, { error: '字段 scenario 必须是字符串' });
407	    return;
408	  }
409	  const rawTitle = body.title as string;
410	  const rawDescription = body.description as string;
411	  const scenario = typeof body.scenario === 'string' ? body.scenario : '';
412	  // 内容规则（空白与上限）与首页共用同一份判定，这里只保留接口原有的错误措辞。
413	  const problem = checkIdeaContent(rawTitle, rawDescription, scenario);
414	  if (problem) {
415	    respond(res, 400, { error: CONTENT_ERROR_MESSAGES[problem] });
416	    return;
417	  }
418	  const { title, description } = normalizeIdea(rawTitle, rawDescription, scenario);
419	  const idea = {
420	    id: randomUUID(),
421	    title,
422	    description,
423	    scenario,
424	    createdAt: new Date().toISOString(),
425	  };
426	  let records: unknown[];
427	  try {
428	    records = readIdeas();
429	  } catch {
430	    respond(res, 500, { error: '无法读取已有意见数据，未保存新意见' });
431	    return;
432	  }
433	  records.unshift(idea);
434	  try {
435	    saveIdeas(records);
436	  } catch {
437	    respond(res, 500, { error: '保存意见失败，请稍后重试' });
438	    return;
439	  }
440	  respond(res, 201, { idea });
441	}
442	const server = createServer((req: IncomingMessage, res: ServerResponse): void => {
443	  let route: string;
444	  try { route = new URL(req.url ?? '/', 'http://localhost').pathname; } catch { respond(res, 400, { error: 'invalid request path' }); return; }
445	  if (!['/', '/health', '/api/ideas'].includes(route)) { respond(res, 404, { error: 'not found' }); return; }
446	  if (route === '/api/ideas') {
447	    if (req.method === 'POST') {
448	      handleCreateIdea(req, res).catch(() => {
449	        if (!res.headersSent) respond(res, 500, { error: '提交意见失败，请稍后重试' });
450	      });
451	      return;
452	    }
453	    if (req.method !== 'GET') { respond(res, 405, { error: 'method not allowed' }, { allow: 'GET, POST' }); return; }
454	    try {
455	      respond(res, 200, { [RESOURCE]: readIdeas() });
456	    } catch { respond(res, 500, { error: 'unable to read ideas' }); }
457	    return;
458	  }
459	  if (req.method !== 'GET') { respond(res, 405, { error: 'method not allowed' }); return; }
460	  if (route === '/') { respond(res, 200, PAGE, { html: true }); return; }
461	  respond(res, 200, { status: 'ok', product: PRODUCT });
462	});
463	server.once('error', (error: Error): void => { console.error(error.message); process.exitCode = 1; });
464	server.listen(port, host, (): void => {
465	  const address = server.address();
466	  if (address && typeof address !== 'string') {
467	    const displayedHost = address.address.includes(':') ? `[${address.address}]` : address.address;
468	    console.log(`${PRODUCT} listening on http://${displayedHost}:${address.port}`);
469	  }
470	});
471	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
472	  process.on(signal, (): void => { server.close(() => { process.exitCode = 0; }); server.closeIdleConnections(); });
473	}
