93	function rawPost({ pieces, chunked = false, delayMs = 2 }: RawOptions): Promise<RawResponse> {
94	  const port = Number(new URL(server.origin).port);
95	  const totalBytes = pieces.reduce((sum, piece) => sum + piece.length, 0);
96	  const headLines = [
97	    'POST /api/ideas HTTP/1.1',
98	    'Host: 127.0.0.1',
99	    'Content-Type: application/json',
100	    'Connection: close',
101	    chunked
102	      ? 'Transfer-Encoding: chunked'
103	      : `Content-Length: ${totalBytes}`,
104	  ];
105	  return new Promise<RawResponse>((resolve, reject) => {
106	    const sock: Socket = connect(port, '127.0.0.1');
107	    let received = Buffer.alloc(0);
108	    let sendingDone = false;
109	    let settled = false;
110	    const fail = (error: Error): void => {
111	      if (settled) return;
112	      settled = true;
113	      sock.destroy();
114	      reject(error);
115	    };
116	    sock.on('error', (error) => fail(error));
117	    sock.on('data', (chunk) => {
118	      // 超限请求必须先排空正文再回复：正文没发完就收到任何字节，
119	      // 说明服务提前响应（或实现退回到读完即断的旧行为）
120	      if (!sendingDone) fail(new Error('服务在请求体发送完成前就返回了数据'));
121	      received = Buffer.concat([received, chunk]);
122	    });
123	    sock.on('end', () => {
124	      if (settled) return;
125	      const split = received.indexOf('\r\n\r\n');
126	      if (split === -1) {
127	        fail(new Error('连接在收到完整响应前结束（只看到连接断开）'));
128	        return;
129	      }
130	      const headerText = received.subarray(0, split).toString('latin1');
131	      const rawBody = received.subarray(split + 4);
132	      const lines = headerText.split('\r\n');
133	      const status = Number((lines[0].match(/HTTP\/1\.1 (\d+)/) ?? [])[1]);
134	      const headers: Record<string, string> = {};
135	      for (const line of lines.slice(1)) {
136	        const at = line.indexOf(':');
137	        if (at > 0) headers[line.slice(0, at).trim().toLowerCase()] = line.slice(at + 1).trim();
138	      }
139	      // 响应必须按声明的长度完整到达，不能被截断
140	      const declared = Number(headers['content-length']);
141	      if (Number.isFinite(declared)) {
142	        assert.equal(rawBody.length, declared, '响应正文应与 content-length 等长');
143	      }
144	      const text = rawBody.toString('utf8');
145	      let json: any;
146	      try {
147	        json = JSON.parse(text);
148	      } catch {
149	        json = undefined;
150	      }
151	      settled = true;
152	      resolve({ status, headers, rawBody, text, json });
153	    });
154	    sock.on('connect', async () => {
155	      try {
156	        await write(sock, headLines.join('\r\n') + '\r\n\r\n');
157	        for (let i = 0; i < pieces.length; i++) {
158	          // 间隔只放在段与段之间：最后一段发出后服务端即可判定请求结束，
159	          // 不能在测试侧再人为拖延，否则会把正常回复误判成“正文没发完就响应”
160	          if (i > 0 && delayMs > 0) await sleep(delayMs);
161	          const piece = pieces[i];
162	          if (chunked) await write(sock, Buffer.from(`${piece.length.toString(16)}\r\n`, 'ascii'));
163	          await write(sock, piece);
164	          if (chunked) await write(sock, Buffer.from('\r\n', 'ascii'));
165	        }
166	        if (chunked) await write(sock, Buffer.from('0\r\n\r\n', 'ascii'));
167	        sendingDone = true;
168	      } catch (error) {
169	        fail(error instanceof Error ? error : new Error(String(error)));
170	      }
171	    });
