185	// 在给定字节偏移处把正文切成多段（偏移允许落在一个多字节字符的 UTF-8 序列内部）
186	function cutAt(body: Buffer, offsets: number[]): Buffer[] {
187	  const sorted = [...new Set(offsets)].filter((o) => o > 0 && o < body.length).sort((a, b) => a - b);
188	  const pieces: Buffer[] = [];
189	  let prev = 0;
190	  for (const offset of sorted) {
191	    pieces.push(body.subarray(prev, offset));
192	    prev = offset;
193	  }
194	  pieces.push(body.subarray(prev));
195	  return pieces;
