408	test('chunked 超限发生在中途：单段都只有十几万字、超限后还有一整段，仍拒绝整次提交', async () => {
409	  // 正文同时不是合法 JSON：超限理由不能被格式错误覆盖。
410	  // 整份做成 1200000 字节、每段 180000：累计在第 6 段中途越过 1000000，
411	  // 越过之后还剩一整段约 12 万字节——若实现只在最后才比较大小就会漏掉这种中途超限
412	  const body = malformedBody(1_200_000);
413	  const pieces: Buffer[] = [];
