312	        const retried = await postIdea(server, NEW_IDEA);
313	        assert.equal(retried.status, 201);
314	        assert.ok(isCompleteSavedIdea(retried.data.idea));
315	        const savedIdea = retried.data.idea as Idea;
316	        assert.equal(savedIdea.title, NEW_IDEA.title);
