1	import { test, before, after } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { connect } from 'node:net';
4	import type { Socket } from 'node:net';
5	import { existsSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
6	import { tmpdir } from 'node:os';
7	import { join } from 'node:path';
8	import { startServer, removeDataDir, type StartedServer } from '../testing/server.ts';
9	
10	// 请求中途断开（正文未完整接收就失去连接）的端到端回归。这里保护的是 POST /api/ideas
11	// 现有的“整次请求的正文接收完整后才判断内容并保存”行为：
12	//   - 发送方明确声明 Content-Length 却只发其中一部分随后断开（FIN 正常关闭或 RST 直接复位），
13	//     即使已收到的前缀恰好是一份可解析的 JSON、三个意见字段都已完整，也不能因为
14	//     文字看起来完整就提前保存；
15	//   - Transfer-Encoding: chunked 下已经发完整个意见的全部文字、但没发“0 长度分块”这一
16	//     请求结束标记就断开，同样属于未完成提交，不能入库；
17	//   - 中断不能损伤已保存的正式内容：数量、顺序、id、createdAt 与三个文字字段逐字保持，
18	//     不留下本次提交的临时保存（.tmp）；没有任何意见时列表仍返回空数组而不是读取失败；
19	//   - 连接已断开时不要求客户端必须收到某种错误响应，关键结果是没有保存意见；
20	//   - 中断后服务继续接受其他请求：查询正常，再完整提交一条合法意见仍返回现有的 201
21	//     和完整保存结果，新意见排在已有意见之前，旧记录内容与相对顺序不变；
22	//   - 完整送达但内容不合法的请求仍按已有规则拒绝（400），中断保护不放宽任何内容判定。
23	// 用原始 TCP 而不是 fetch：fetch 无法刻意少发 Content-Length 声明的字节，
24	// 也无法在 chunked 请求里省略结束标记后断开。
25	
26	interface Idea {
27	  id: string;
28	  title: string;
29	  description: string;
30	  scenario: string;
31	  createdAt: string;
32	}
33	
34	// 被中断的那条意见：三个字段都符合当前规则（标题去空白后非空且不超过 120 码点、
35	// 说明含非空白内容且不超过 5000、场景不超过 1000），整份 JSON 远低于 1000000 字节上限。
36	// 完整发送时必须能保存——否则“没保存”就可能只是内容被拒，而不是中断处理的结果。
37	const INTERRUPTED = {
38	  title: '中断的意见标题',
39	  description: '这一条的标题、详细说明与使用场景都合法，\n完整发送时应当可以保存。  ',
40	  scenario: '使用场景：中途断开，含中文与表情 😮‍💨🌙',
41	};
42	const FULL_BODY = Buffer.from(JSON.stringify(INTERRUPTED), 'utf8');
43	const points = (text: string): number => Array.from(text).length;
44	assert.ok(points(INTERRUPTED.title.trim()) > 0 && points(INTERRUPTED.title.trim()) <= 120);
45	assert.ok(INTERRUPTED.description.trim().length > 0 && points(INTERRUPTED.description) <= 5000);
46	assert.ok(points(INTERRUPTED.scenario) <= 1000);
47	assert.ok(FULL_BODY.length < 1_000_000, '中断的意见整份请求体应低于已有大小上限');
48	JSON.parse(FULL_BODY.toString('utf8')); // 整份（以及作为“完整前缀”使用时）是可解析 JSON
49	
50	// 已有意见要覆盖易被破坏的文字：标题首尾空白、正文与场景里的空白、换行、中文与表情；
51	// 另放两条三字段完全相同、只能靠 id 区分的记录，防止中断把它们合并或重写。
52	const SEEDS = [
53	  {
54	    title: '  已有意见 甲 ',
