102	// 等服务侧把这次中断请求处理完：响应无处可写，唯一可观察的副作用就是“没有写入”。
103	// 用轮询而不是固定长睡：连接关闭事件传到服务、请求流结束、处理 Promise 落定都需要一拍，
104	// 期间服务绝不能有任何落盘；连续一小段时间列表与磁盘都稳定不变，才进入后续断言。
105	async function settle(): Promise<void> {
106	  for (let i = 0; i < 50; i++) {
107	    const list = await listIdeas();
108	    const disk = readFileSync(ideasFile());
109	    if (list.length === baseline.length && disk.equals(baselineDisk)) {
