128	// 在字节偏移处把正文切成多段（偏移可以落在一个多字节字符的 UTF-8 序列内部）
129	function cutAt(body: Buffer, offsets: number[]): Buffer[] {
130	  const sorted = [...new Set(offsets)].filter((o) => o > 0 && o < body.length).sort((a, b) => a - b);
131	  const pieces: Buffer[] = [];
132	  let prev = 0;
133	  for (const offset of sorted) {
134	    pieces.push(body.subarray(prev, offset));
135	    prev = offset;
136	  }
137	  pieces.push(body.subarray(prev));
138	  return pieces;
139	}
