141	function requestHead(extraLine: string): string {
142	  return [
143	    'POST /api/ideas HTTP/1.1',
144	    'Host: 127.0.0.1',
145	    'Content-Type: application/json',
146	    extraLine,
147	    'Connection: close',
148	  ].join('\r\n') + '\r\n\r\n';
149	}
