151	// 打开一条原始连接，按 sender 逐段发送，结束时以 FIN（end）或 RST（resetAndDestroy）断开。
152	// 全程不读取响应：连接已断开时不要求客户端收到任何错误，这里只制造“未发完就失去连接”。
153	function openInterruptingConnection(
154	  sender: (sock: Socket, done: () => void) => Promise<void>,
155	  mode: 'fin' | 'rst',
156	): Promise<void> {
157	  const port = Number(new URL(server.origin).port);
158	  return new Promise((resolve, reject) => {
159	    const sock = connect(port, '127.0.0.1');
160	    let settled = false;
161	    // 不校验响应内容（连接已断开，不要求客户端收到某种错误），但必须排空：
162	    // 否则收到 FIN 的一侧保持暂停，'close' 不触发，辅助 Promise 会挂住。
163	    sock.resume();
164	    sock.on('error', () => {
165	      // 断开后服务回收 socket 可能回 RST/FIN：客户端本来就不期待响应，忽略即可
166	    });
167	    sock.on('close', () => {
168	      settled = true;
169	      resolve();
170	    });
171	    sock.on('connect', () => {
172	      sender(sock, () => {
173	        if (mode === 'rst') sock.resetAndDestroy();
174	        else sock.end();
175	      }).catch((error) => {
176	        if (!settled) sock.destroy();
177	        reject(error instanceof Error ? error : new Error(String(error)));
178	      });
179	    });
180	  });
181	}
