183	// 中断后统一的数据保护断言：正式保存内容与中断前逐字一致，不残留本次临时内容
184	async function assertNothingSaved(): Promise<void> {
185	  const list = await listIdeas();
186	  assert.deepEqual(list, baseline, '中断的意见不能进入已保存列表，已有记录也不能变化');
187	  assert.deepEqual(readFileSync(ideasFile()), baselineDisk, '正式保存内容不能被中断清空、重写或混入前缀');
188	  assert.ok(!existsSync(`${ideasFile()}.tmp`), '不能留下本次提交的临时保存内容');
189	
190	  // 已有意见的标识与提交时间原样保留；文字里的空白、换行、中文与表情逐字不变
191	  const oldest = list[list.length - 1];
192	  assert.equal(oldest.title, '已有意见 甲');
193	  assert.equal(oldest.description, '第一行\n第二行 含空格、中文 与 😀\n  首尾空格也保留  ');
194	  assert.equal(oldest.scenario, ' 场景甲：换行\n与表情 🌙 ');
195	  const twins = list.filter((idea) => idea.title === '同标题同正文');
196	  assert.equal(twins.length, 2);
197	  assert.notEqual(twins[0].id, twins[1].id);
198	  for (const idea of twins) {
199	    assert.ok(baseline.some((old) => old.id === idea.id && old.createdAt === idea.createdAt));
200	  }
201	  // 被中断那条的文字一个字都不能出现在列表里
202	  for (const idea of list) {
203	    assert.notEqual(idea.title, INTERRUPTED.title);
204	    assert.notEqual(idea.description, INTERRUPTED.description);
205	  }
206	}
