400	// 与 openInterruptingConnection 相同，但显式指定服务实例（空数据目录用例使用独立服务）
401	function openInterruptingConnectionOn(
402	  target: StartedServer,
403	  sender: (sock: Socket) => Promise<void>,
404	  mode: 'fin' | 'rst',
405	): Promise<void> {
406	  const port = Number(new URL(target.origin).port);
407	  return new Promise((resolve, reject) => {
408	    const sock = connect(port, '127.0.0.1');
409	    let settled = false;
410	    // 同 openInterruptingConnection：排空数据，'close' 才会触发
411	    sock.resume();
412	    sock.on('error', () => { /* 断开后不期待响应，忽略 */ });
413	    sock.on('close', () => {
414	      settled = true;
415	      resolve();
416	    });
417	    sock.on('connect', () => {
418	      sender(sock)
419	        .then(() => {
420	          if (mode === 'rst') sock.resetAndDestroy();
421	          else sock.end();
422	        })
423	        .catch((error) => {
424	          if (!settled) sock.destroy();
425	          reject(error instanceof Error ? error : new Error(String(error)));
426	        });
427	    });
428	  });
429	}
