// 与 openInterruptingConnection 相同，但显式指定服务实例（空数据目录用例使用独立服务）
function openInterruptingConnectionOn(
  target: StartedServer,
  sender: (sock: Socket) => Promise<void>,
  mode: 'fin' | 'rst',
): Promise<void> {
  const port = Number(new URL(target.origin).port);
  return new Promise((resolve, reject) => {
    const sock = connect(port, '127.0.0.1');
    let settled = false;
    // 同 openInterruptingConnection：排空数据，'close' 才会触发
    sock.resume();
    sock.on('error', () => { /* 断开后不期待响应，忽略 */ });
    sock.on('close', () => {
      settled = true;
      resolve();
    });
    sock.on('connect', () => {
      sender(sock)
        .then(() => {
          if (mode === 'rst') sock.resetAndDestroy();
          else sock.end();
        })
        .catch((error) => {
          if (!settled) sock.destroy();
          reject(error instanceof Error ? error : new Error(String(error)));
        });
    });
  });
}

